const picker=document.querySelector('#page-picker'),sectionPicker=document.querySelector('#section-picker'),frame=document.querySelector('#preview'),form=document.querySelector('#field-form'),empty=document.querySelector('#empty'),productBox=document.querySelector('#product-inspector'),publicLink=document.querySelector('#public-link'),elementList=document.querySelector('#element-list'),elementCount=document.querySelector('#element-count'),inspectorClose=document.querySelector('#inspector-close'),inspectorReopen=document.querySelector('#inspector-reopen');let selected=null,editable=[],mediaLibrary=null,richTextState={es:[],en:[]},textSelection=null;const fieldLabels=new Map();
