async function submitJson(url,body,timeout=60000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(url,{method:'POST',body,credentials:'same-origin',headers:{Accept:'application/json'},signal:controller.signal}),text=await response.text();let payload={};try{payload=text?JSON.parse(text):{}}catch(_){throw new Error('El servidor devolvió una respuesta inválida.')}if(!response.ok)throw new Error(payload.error||'No se pudo guardar el cambio.');return payload}finally{clearTimeout(timer)}}
function cssColorToHex(value){const match=String(value||'').match(/rgba?\((\d+)[, ]+(\d+)[, ]+(\d+)/i);return match?'#'+match.slice(1,4).map(part=>Number(part).toString(16).padStart(2,'0')).join(''):''}
