function syncRichText(){richTextInput.value=JSON.stringify(richTextState)}
function validRuns(lang,value){const runs=Array.isArray(richTextState[lang])?richTextState[lang]:[];return runs.length&&runs.every(run=>run&&typeof run.text==='string'&&(!run.color||/^#[0-9a-f]{6}$/i.test(run.color)))&&runs.map(run=>run.text).join('')===value?runs:[{text:value}]}
function renderRichTextPreview(element,value,runs){if(!element)return;const preserveChildren=element.querySelector(':scope > svg, :scope > img, :scope > span:not([data-cms-run])');if(preserveChildren){const node=Array.from(element.childNodes).find(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim());if(node)node.textContent=value;else element.append(document.createTextNode(value));return}element.replaceChildren(...runs.map(run=>{if(!run.color)return document.createTextNode(run.text);const span=document.createElement('span');span.dataset.cmsRun='color';span.style.color=run.color;span.textContent=run.text;return span}))}
function resetSelection(message='Selecciona palabras directamente en la vista.'){textSelection=null;selectionStatus.textContent=message;applySelectionButton.disabled=true;clearSelectionButton.disabled=true}
function captureSelection(){const doc=frame.contentDocument,selection=doc?.getSelection();if(!doc||!selected||!selection||selection.rangeCount===0||selection.isCollapsed)return false;const range=selection.getRangeAt(0);if(!selected.contains(range.startContainer)||!selected.contains(range.endContainer))return false;const before=doc.createRange();before.selectNodeContents(selected);before.setEnd(range.startContainer,range.startOffset);const through=doc.createRange();through.selectNodeContents(selected);through.setEnd(range.endContainer,range.endOffset);const start=before.toString().length,end=through.toString().length;if(end<=start)return false;textSelection={start,end};selectionStatus.textContent='Selección lista: “'+range.toString().trim().slice(0,70)+'”';applySelectionButton.disabled=false;clearSelectionButton.disabled=false;return true}
function applyPartialColor(color){if(!selected||!textSelection)return;const range={...textSelection},lang=current().lang,input=form.elements['value_'+lang],value=input.value,runs=validRuns(lang,value),colors=Array(value.length).fill('');frame.contentDocument?.getSelection()?.removeAllRanges();textSelection=null;applySelectionButton.disabled=true;clearSelectionButton.disabled=true;let offset=0;runs.forEach(run=>{for(let index=0;index<run.text.length;index++)colors[offset+index]=run.color||'';offset+=run.text.length});for(let index=range.start;index<Math.min(range.end,value.length);index++)colors[index]=color;const next=[];for(let index=0;index<value.length;){const currentColor=colors[index]||'',start=index;while(index<value.length&&(colors[index]||'')===currentColor)index++;const run={text:value.slice(start,index)};if(currentColor)run.color=currentColor;next.push(run)}richTextState[lang]=next;syncRichText();renderRichTextPreview(selected,value,next);selectionStatus.textContent=color?'Color aplicado. Guarda para publicarlo.':'Color parcial eliminado. Guarda para publicarlo.'}
applySelectionButton.addEventListener('click',()=>applyPartialColor(selectionColor.value));clearSelectionButton.addEventListener('click',()=>applyPartialColor(''));['es','en'].forEach(lang=>form.elements['value_'+lang].addEventListener('input',()=>{const value=form.elements['value_'+lang].value;if((richTextState[lang]||[]).map(run=>run.text).join('')!==value)richTextState[lang]=[];syncRichText();resetSelection('El texto cambió. Selecciona nuevamente en la vista.')}));
