function labelFor(element){if(element instanceof HTMLImageElement)return element.alt||'Imagen';const text=(element.textContent||'').trim().replace(/\s+/g,' ');return text.slice(0,58)||element.dataset.cms}
function refreshElements(){const section=sectionPicker.value;const filtered=section?editable.filter(element=>element.dataset.cms?.split('.')[0]===section):editable;elementList.innerHTML='';filtered.forEach(element=>{const button=document.createElement('button');button.type='button';button.innerHTML='<span></span><small></small>';button.querySelector('span').textContent=fieldLabels.get(element.dataset.cms)||labelFor(element);button.querySelector('small').textContent=element.tagName.toLowerCase();button.addEventListener('click',()=>{element.scrollIntoView({behavior:'smooth',block:'center'});showField(element.dataset.cms,element,button)});elementList.append(button)});elementCount.textContent=filtered.length+' elementos';if(!filtered.length)elementList.innerHTML='<span>No hay elementos editables en esta sección.</span>'}
sectionPicker.addEventListener('change',()=>{resetInspector();refreshElements();const doc=frame.contentDocument,section=doc?.querySelector('[data-cms-section="'+CSS.escape(sectionPicker.value)+'"]');section?.scrollIntoView({behavior:'smooth',block:'start'})});
frame.addEventListener('load',()=>{const doc=frame.contentDocument;if(!doc)return;const style=doc.createElement('style');style.textContent='[data-cms],[data-product-id]{cursor:pointer!important;outline:1px dashed transparent!important;outline-offset:4px;transition:outline-color .2s,box-shadow .2s}[data-cms]:hover,[data-product-id]:hover{outline-color:#79b855!important;box-shadow:0 0 0 5px #c6ee9b33!important}';doc.head.append(style);const collect=()=>{editable=Array.from(doc.querySelectorAll('[data-cms]'));const sections=[...new Set(editable.map(element=>element.dataset.cms.split('.')[0]))];const selectedSection=sectionPicker.value;sectionPicker.innerHTML='<option value="">Todas las secciones</option>'+sections.map(section=>'<option value="'+section+'">'+section.replace(/-/g,' ')+'</option>').join('');if(sections.includes(selectedSection))sectionPicker.value=selectedSection;refreshElements()};let collectTimer=0;const observer=new MutationObserver(()=>{clearTimeout(collectTimer);collectTimer=setTimeout(collect,80)});observer.observe(doc.body,{childList:true,subtree:true});collect();frame.addEventListener('load',()=>observer.disconnect(),{once:true});frame.contentWindow.addEventListener('royalbeans:cms-ready',collect,{once:true});doc.addEventListener('submit',event=>event.preventDefault(),true);doc.addEventListener('mouseup',()=>captureSelection(),true);doc.addEventListener('click',event=>{const target=event.target.closest('[data-cms],[data-product-id]');event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();if(captureSelection())return;if(!target)return;if(target.dataset.productId){showProduct(target.dataset.productId);return}showField(target.dataset.cms,target)},true)});
async function showField(key,element,listButton){document.body.classList.remove('inspector-collapsed');selected=element;resetSelection();empty.hidden=true;productBox.hidden=true;form.hidden=false;document.querySelectorAll('.element-list button').forEach(button=>button.classList.toggle('active',button===listButton));const item=current(),needsMedia=element instanceof HTMLImageElement&&mediaLibrary===null,response=await fetch('/admin/editor-api.php?page='+encodeURIComponent(item.page)+'&key='+encodeURIComponent(key)+'&include_media='+(needsMedia?'1':'0'),{credentials:'same-origin',cache:'no-store'}),payload=await response.json(),field=payload.field,style=typeof field.style_json==='string'?JSON.parse(field.style_json||'{}'):(field.style_json||{});form.page_key.value=item.page;form.key.value=key;form.editing_lang.value=item.lang;const detected=element instanceof HTMLImageElement?'image':((element.textContent||'').trim().length>90?'textarea':'text');form.field_type.value=field.id?field.field_type:detected;form.label.value=field.id?field.label:labelFor(element);fieldLabels.set(key,form.label.value);form.value_es.value=field.value_es||(item.lang==='es'?(element instanceof HTMLImageElement?(element.getAttribute('src')||''):element.textContent.trim()):'');form.value_en.value=field.value_en||(item.lang==='en'?(element instanceof HTMLImageElement?(element.getAttribute('src')||''):element.textContent.trim()):'');form.font_family.value=style.font||'';richTextState={es:Array.isArray(style.richText?.es)?style.richText.es:[],en:Array.isArray(style.richText?.en)?style.richText.en:[]};const hasRichText=richTextState.es.length>0||richTextState.en.length>0,legacyDefault=String(style.color||'').toLowerCase()==='#303a35'&&hasRichText,originalColor=originalTextColor(element);if(legacyDefault)element.style.removeProperty('color');form.text_color.value=legacyDefault?(originalColor||'#303a35'):(style.color||originalColor||'#303a35');wholeTextColor.dataset.explicit=style.color&&!legacyDefault?'1':'0';form.font_size.value=style.size||'';syncRichText();syncLanguageControls(item.lang);document.querySelector('#field-name').textContent=form.label.value;const imageMode=form.field_type.value==='image';if(imageMode&&mediaLibrary===null)mediaLibrary=Array.isArray(payload.media)?payload.media:[];setImageMode(imageMode,item.lang==='en'?form.value_en.value:form.value_es.value,mediaLibrary||[])}
function showProduct(id){document.body.classList.remove('inspector-collapsed');empty.hidden=true;form.hidden=true;productBox.hidden=false;document.querySelector('#product-edit-link').href='/admin/product-details.php?id='+id}
form.label.addEventListener('input',()=>{if(!form.key.value)return;fieldLabels.set(form.key.value,form.label.value);document.querySelector('#field-name').textContent=form.label.value||'Contenido'});
inspectorClose.addEventListener('click',()=>document.body.classList.add('inspector-collapsed'));inspectorReopen.addEventListener('click',()=>document.body.classList.remove('inspector-collapsed'));form.field_type.addEventListener('change',()=>setImageMode(form.field_type.value==='image'));form.addEventListener('submit',async event=>{event.preventDefault();const state=form.querySelector('.save-state'),button=form.querySelector('.save-bar button');state.textContent='Guardando…';button.disabled=true;try{const payload=await submitJson('/admin/editor-api.php',fieldPayload()),lang=current().lang,value=payload[lang==='en'?'value_en':'value_es'];richTextState={es:Array.isArray(payload.style?.richText?.es)?payload.style.richText.es:[],en:Array.isArray(payload.style?.richText?.en)?payload.style.richText.en:[]};syncRichText();if(selected){if(payload.type==='image'&&selected instanceof HTMLImageElement){selected.hidden=!value;if(value)selected.src=value;else selected.removeAttribute('src');selected.closest('picture')?.querySelectorAll('source').forEach(source=>{if(value)source.srcset=value;else source.removeAttribute('srcset')})}else if(payload.type==='url'&&selected instanceof HTMLAnchorElement)selected.href=value;else if(payload.type!=='image')renderRichTextPreview(selected,value,validRuns(lang,value))}if(selected&&payload.style&&payload.type!=='image'){const fonts={display:'var(--font-display-active,var(--font-display))',body:'var(--font-body-active,var(--font-body))',editorial:"Georgia, 'Times New Roman', serif"};selected.style.fontFamily=fonts[payload.style.font]||'';selected.style.color=payload.style.color||'';selected.style.fontSize=payload.style.size?payload.style.size+'px':''}wholeTextColor.dataset.explicit=payload.style?.color?'1':'0';removeInput.value='';resetSelection('Cambios guardados en la base de datos.');state.textContent='Cambios guardados';refreshElements();setTimeout(()=>state.textContent='',1800)}catch(error){removeInput.value='';state.textContent=error.name==='AbortError'?'El guardado tardó demasiado. Inténtalo otra vez.':error.message}finally{button.disabled=false}});
</script><style>
.element-list{max-height:min(34vh,320px)}
.image-tools{display:grid;gap:12px;padding:14px;border:1px solid #dce5df;border-radius:10px;background:#f8faf7}.image-tools[hidden]{display:none}.image-current{display:grid;gap:8px}.image-current>span{color:#52665d;font-size:11px;font-weight:750;text-transform:uppercase}.image-current img{width:100%;max-height:210px;object-fit:contain;border:1px solid #d7dfda;border-radius:8px;background:#edf1eb}.image-current p{margin:0;padding:22px;border:1px dashed #c8d2ca;border-radius:8px;color:#6c7972;text-align:center}.remove-image-button{min-height:42px;padding:9px 12px;border:1px solid #d9a6a6;border-radius:7px;color:#8c2929;background:#fff7f7;font-weight:750;cursor:pointer}.image-tools small{color:#6c7972;line-height:1.45}
.selection-color-tools{display:grid;gap:8px;margin-top:4px;padding:12px;border:1px solid #dce5df;border-radius:8px;background:#f8faf7}.selection-color-tools>strong{font-size:12px}.selection-color-tools>p{min-height:32px;margin:0;color:#607169;font-size:11px;font-weight:500;line-height:1.45}.selection-color-tools>div{display:grid;grid-template-columns:48px 1fr 1fr;gap:7px}.selection-color-tools input{height:40px;padding:3px!important}.selection-color-tools button{min-height:40px;padding:8px;border:1px solid #9fca7d;border-radius:7px;color:#06382e;background:#edf8e4;font-size:11px;font-weight:750}.selection-color-tools button:disabled{cursor:not-allowed;opacity:.45}
.hero-settings-button{width:100%;min-height:46px;display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding:11px 12px;border:1px solid #9fca7d;border-radius:8px;color:#06382e;background:#edf8e4;font-size:12px;font-weight:750;text-align:left}
.hero-settings-button:hover{background:#dff2cf}.hero-settings-button[hidden]{display:none}
.hero-form fieldset{display:grid;gap:12px;margin:0;padding:14px;border:1px solid #dce5df;border-radius:8px}.hero-form legend{padding:0 6px;color:#52665d;font-size:11px;font-weight:750;text-transform:uppercase}
.hero-range{display:grid;grid-template-columns:1fr auto;gap:7px;align-items:center}.hero-range input{grid-column:1/-1;padding:0}.hero-range output{font-variant-numeric:tabular-nums;color:#075e53}
