@media(max-width:850px){.element-list{max-height:min(27vh,230px)}}
</style><script>
(()=>{const editorFrame=document.querySelector('#preview'),pagePicker=document.querySelector('#page-picker'),browser=document.querySelector('.element-browser'),content=document.querySelector('.inspector-content'),regularForm=document.querySelector('#field-form'),emptyState=document.querySelector('#empty'),productInspector=document.querySelector('#product-inspector');
const heroButton=document.createElement('button');heroButton.id='hero-settings';heroButton.className='hero-settings-button';heroButton.type='button';heroButton.hidden=true;heroButton.innerHTML='<span>Configurar hero de esta página</span><small>Imagen · altura · opacidad</small>';browser.querySelector('.element-browser-head').after(heroButton);
const heroForm=document.createElement('form');heroForm.className='inspector-form hero-form';heroForm.hidden=true;heroForm.enctype='multipart/form-data';heroForm.innerHTML='<p class="admin-eyebrow">Hero de la página</p><h2>Imagen y composición</h2><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="page_key"><input type="hidden" name="key" value="hero.image"><input type="hidden" name="editing_lang"><input type="hidden" name="field_type" value="image"><input type="hidden" name="label" value="Imagen principal del hero"><input type="hidden" name="value_es"><input type="hidden" name="value_en"><label>Nueva imagen del hero<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/avif"><small>Se utilizará la misma imagen en español e inglés.</small></label><fieldset><legend>Tamaño y apariencia</legend><label class="hero-range"><span>Altura del hero</span><output id="hero-height-output">620 px</output><input type="range" name="hero_height" min="360" max="950" step="10" value="620"></label><label class="hero-range"><span>Opacidad verde</span><output id="hero-overlay-output">72 %</output><input type="range" name="hero_overlay" min="0" max="90" step="1" value="72"></label><label class="hero-toggle"><input type="checkbox" name="hero_show_text" value="1" checked><span>Mostrar textos y logotipo del hero</span></label></fieldset><div class="save-bar"><button>Guardar configuración del hero</button><p class="save-state" role="status"></p></div>';content.prepend(heroForm);
const heroMarker=document.createElement('input');heroMarker.type='hidden';heroMarker.name='hero_settings_present';heroMarker.value='1';heroForm.append(heroMarker);const heroRemove=document.createElement('input');heroRemove.type='hidden';heroRemove.name='remove_image';heroForm.append(heroRemove);const heroLibrary=document.createElement('label');heroLibrary.innerHTML='O elegir de la biblioteca R2<select name="selected_media"><option value="">Conservar imagen actual</option></select>';heroForm.querySelector('fieldset').before(heroLibrary);const heroRemoveButton=document.createElement('button');heroRemoveButton.type='button';heroRemoveButton.className='remove-image-button';heroRemoveButton.textContent='Quitar imagen del hero';heroForm.querySelector('.save-bar').before(heroRemoveButton);
const item=()=>{const option=pagePicker.selectedOptions[0];return{page:option.dataset.page,lang:option.dataset.lang}};const field=name=>heroForm.elements.namedItem(name);const updateOutputs=()=>{document.querySelector('#hero-height-output').textContent=field('hero_height').value+' px';document.querySelector('#hero-overlay-output').textContent=field('hero_overlay').value+' %'};
async function openHero(){const image=editorFrame.contentDocument?.querySelector('[data-hero] [data-cms="hero.image"]');if(!image)return;document.body.classList.remove('inspector-collapsed');regularForm.hidden=true;emptyState.hidden=true;productInspector.hidden=true;heroForm.hidden=false;const current=item(),response=await fetch('/admin/editor-api.php?page='+encodeURIComponent(current.page)+'&key=hero.image&include_media='+(mediaLibrary===null?'1':'0')),payload=await response.json(),stored=payload.field||{},style=typeof stored.style_json==='string'?JSON.parse(stored.style_json||'{}'):(stored.style_json||{}),imagePath=image.getAttribute('src')||'';if(mediaLibrary===null)mediaLibrary=Array.isArray(payload.media)?payload.media:[];field('page_key').value=current.page;field('editing_lang').value=current.lang;field('value_es').value=stored.value_es||imagePath;field('value_en').value=stored.value_en||imagePath;field('hero_height').value=style.heroHeight||Math.round(image.closest('[data-hero]').getBoundingClientRect().height)||620;field('hero_overlay').value=style.heroOverlay??72;field('hero_show_text').checked=style.heroShowText!==false;field('remove_image').value='';field('selected_media').innerHTML='<option value="">Conservar imagen actual</option>'+((mediaLibrary||[]).map(media=>'<option value="'+String(media.path).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'">'+String(media.original_name||media.path).replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</option>').join(''));updateOutputs()}
const refreshHeroButton=()=>{heroButton.hidden=!editorFrame.contentDocument?.querySelector('[data-hero] [data-cms="hero.image"]')};heroButton.addEventListener('click',openHero);heroForm.querySelectorAll('input[type="range"]').forEach(input=>input.addEventListener('input',updateOutputs));document.querySelector('#element-list').addEventListener('click',()=>heroForm.hidden=true);pagePicker.addEventListener('change',()=>{heroForm.hidden=true;heroButton.hidden=true});editorFrame.addEventListener('load',()=>{refreshHeroButton();editorFrame.contentWindow?.addEventListener('royalbeans:cms-ready',refreshHeroButton,{once:true})});refreshHeroButton();
heroRemoveButton.addEventListener('click',()=>{if(!confirm('El hero conservará sus textos, pero quedará sin imagen. Si el archivo no tiene otros usos, también se eliminará de Cloudflare R2. ¿Continuar?'))return;field('remove_image').value='1';field('selected_media').value='';heroForm.querySelector('input[type="file"]').value='';heroForm.requestSubmit()});
heroForm.addEventListener('submit',async event=>{event.preventDefault();const state=heroForm.querySelector('.save-state'),button=heroForm.querySelector('.save-bar button');state.textContent='Guardando…';button.disabled=true;try{await submitJson('/admin/editor-api.php',new FormData(heroForm),30000);field('remove_image').value='';state.textContent='Hero actualizado';editorFrame.contentWindow.location.reload()}catch(error){field('remove_image').value='';state.textContent=error.name==='AbortError'?'El guardado tardó demasiado. Inténtalo otra vez.':error.message}finally{button.disabled=false}});})();
</script><script>
(()=>{const picker=document.querySelector('#page-picker'),browser=document.querySelector('.element-browser');if(!picker||!browser)return;const link=document.createElement('a');link.href='/admin/about-videos.php';link.className='hero-settings-button';link.textContent='Subir videos de Nosotros · Español / English';const sync=()=>{link.hidden=picker.selectedOptions[0]?.dataset.page!=='nosotros'};browser.querySelector('.element-browser-head')?.after(link);picker.addEventListener('change',sync);sync()})();
</script></body></html>
